import { Controller, Get, Post, Patch, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const HR_ROLE = '인사 담당자';
const ITEM_TYPES = ['가족', '학력', '경력', '자격·면허', '외국어', '인사고과', '상벌', '출장', '부양가족', '병역', '보훈'];
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

function invalid(message: string): ApiError {
  return new ApiError(422, 'HR_CARD_ITEM_INVALID', message);
}

function textOf(v: unknown, max: number, label: string, required: boolean): string | null {
  if (v === undefined || v === null || v === '') {
    if (required) {
      throw invalid(label + '을(를) 입력해 주세요.');
    }
    return null;
  }
  if (typeof v !== 'string') {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  if (required && v.trim() === '') {
    throw invalid(label + '을(를) 입력해 주세요.');
  }
  if (v.length > max) {
    throw invalid(label + '은(는) ' + max + '자 이하로 입력해 주세요.');
  }
  return v;
}

function dateOf(v: unknown, label: string): string | null {
  if (v === undefined || v === null || v === '') {
    return null;
  }
  if (typeof v !== 'string' || !DATE_RE.test(v)) {
    throw invalid(label + ' 형식이 올바르지 않습니다. (YYYY-MM-DD)');
  }
  return v;
}

function idOf(v: unknown, label: string): number {
  if (typeof v === 'number' && Number.isInteger(v) && v > 0) {
    return v;
  }
  if (typeof v === 'string' && /^\d+$/.test(v) && Number(v) > 0) {
    return Number(v);
  }
  throw invalid(label + ' 형식이 올바르지 않습니다.');
}

function checkPeriod(start: string | null, end: string | null): void {
  // YYYY-MM-DD 형식은 글자 순서가 날짜 순서와 같다
  if (start !== null && end !== null && start > end) {
    throw invalid('시작일이 종료일보다 늦을 수 없습니다.');
  }
}

// TODO: relatedPersonRrn(관련자 주민등록번호) 암호화 저장은 암호화 모듈·키 출처가 없어 구현하지 못했다. 요청에 와도 저장하지 않는다.
// TODO: 등록·수정 변경 이력과 개인정보 접속·사용 로그는 이력·로그 테이블이 없어 구현하지 못했다.

@Controller('api/v1')
export class FnSfr01205Controller {
  @Get('/hr-card-items')
  async listHrCardItems(@Req() req: Request) {
    const user = currentUser(req);
    user.require(HR_ROLE);
    const query = checks.queryOf(req.query);
    const rawEmployeeId = query['employeeId'];
    if (rawEmployeeId === undefined || rawEmployeeId === null || rawEmployeeId === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID를 입력해 주세요.');
    }
    if (!/^\d+$/.test(String(rawEmployeeId))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '임직원 ID 형식이 올바르지 않습니다.');
    }
    const employeeId = Number(rawEmployeeId);
    let itemType: string | null = null;
    if (query['itemType'] !== undefined && query['itemType'] !== null && query['itemType'] !== '') {
      itemType = String(query['itemType']);
      if (!ITEM_TYPES.includes(itemType)) {
        throw new ApiError(400, 'VALIDATION_FAILED', '항목 유형이 올바르지 않습니다.');
      }
    }
    let page = 0;
    if (query['page'] !== undefined && query['page'] !== '') {
      if (!/^\d+$/.test(String(query['page']))) {
        throw new ApiError(400, 'VALIDATION_FAILED', '페이지 번호 형식이 올바르지 않습니다.');
      }
      page = Number(query['page']);
    }
    let size = DEFAULT_SIZE;
    if (query['size'] !== undefined && query['size'] !== '') {
      if (!/^\d+$/.test(String(query['size'])) || Number(query['size']) < 1) {
        throw new ApiError(400, 'VALIDATION_FAILED', '페이지 크기 형식이 올바르지 않습니다.');
      }
      size = Math.min(Number(query['size']), MAX_SIZE);
    }
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '대상 임직원이 존재하지 않습니다.');
      }
      const params = { employeeId, itemType, limit: size, offset: page * size };
      const totals = await db.query(
        `SELECT COUNT(*) AS "total"
         FROM hr_card_item
         WHERE employee_id = CAST(:employeeId AS bigint)
           AND (CAST(:itemType AS varchar) IS NULL OR item_type = CAST(:itemType AS varchar))`,
        params,
      );
      const items = await db.query(
        `SELECT hr_card_item_id AS "hrCardItemId",
                employee_id AS "employeeId",
                item_type AS "itemType",
                title AS "title",
                detail AS "detail",
                start_date AS "startDate",
                end_date AS "endDate",
                related_person_name AS "relatedPersonName"
         FROM hr_card_item
         WHERE employee_id = CAST(:employeeId AS bigint)
           AND (CAST(:itemType AS varchar) IS NULL OR item_type = CAST(:itemType AS varchar))
         ORDER BY hr_card_item_id DESC
         LIMIT CAST(:limit AS integer) OFFSET CAST(:offset AS integer)`,
        params,
      );
      return { items, page, size, total: Number(totals[0]['total']) };
    });
  }

  @Post('/hr-card-items')
  @HttpCode(200)
  async createHrCardItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(HR_ROLE);
    const data = checks.inputOf(req.body);
    const employeeId = idOf(data['employeeId'], '임직원 ID');
    const itemType = textOf(data['itemType'], 30, '항목 유형', true) as string;
    if (!ITEM_TYPES.includes(itemType)) {
      throw invalid('항목 유형이 올바르지 않습니다.');
    }
    const title = textOf(data['title'], 200, '항목명', true) as string;
    const detail = textOf(data['detail'], 100000, '상세 내용', false);
    const startDate = dateOf(data['startDate'], '시작일');
    const endDate = dateOf(data['endDate'], '종료일');
    const relatedPersonName = textOf(data['relatedPersonName'], 100, '관련자명', false);
    checkPeriod(startDate, endDate);
    return transaction(async (db) => {
      const employees = await db.query(
        'SELECT employee_id FROM employee WHERE employee_id = CAST(:employeeId AS bigint)',
        { employeeId },
      );
      if (employees.length === 0) {
        throw new ApiError(404, 'EMPLOYEE_NOT_FOUND', '대상 임직원이 존재하지 않습니다.');
      }
      const rows = await db.query(
        `INSERT INTO hr_card_item
           (employee_id, item_type, title, detail, start_date, end_date, related_person_name, created_at, updated_at)
         VALUES
           (CAST(:employeeId AS bigint), :itemType, :title, :detail, CAST(:startDate AS date), CAST(:endDate AS date), :relatedPersonName, now(), now())
         RETURNING hr_card_item_id AS "hrCardItemId"`,
        { employeeId, itemType, title, detail, startDate, endDate, relatedPersonName },
      );
      return { hrCardItemId: Number(rows[0]['hrCardItemId']) };
    });
  }

  @Patch('/hr-card-items/:hrCardItemId')
  async updateHrCardItem(@Req() req: Request) {
    const user = currentUser(req);
    user.require(HR_ROLE);
    const rawId = req.params['hrCardItemId'];
    if (!/^\d+$/.test(rawId)) {
      throw new ApiError(404, 'HR_CARD_ITEM_NOT_FOUND', '대상 항목이 존재하지 않습니다.');
    }
    const hrCardItemId = Number(rawId);
    const data = checks.inputOf(req.body);
    let title: string | null = null;
    if (data['title'] !== undefined && data['title'] !== null) {
      title = textOf(data['title'], 200, '항목명', true);
    }
    const detail = textOf(data['detail'], 100000, '상세 내용', false);
    const startDate = dateOf(data['startDate'], '시작일');
    const endDate = dateOf(data['endDate'], '종료일');
    const relatedPersonName = textOf(data['relatedPersonName'], 100, '관련자명', false);
    return transaction(async (db) => {
      const found = await db.query(
        `SELECT to_char(start_date, 'YYYY-MM-DD') AS "startDate",
                to_char(end_date, 'YYYY-MM-DD') AS "endDate"
         FROM hr_card_item
         WHERE hr_card_item_id = CAST(:hrCardItemId AS bigint)`,
        { hrCardItemId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'HR_CARD_ITEM_NOT_FOUND', '대상 항목이 존재하지 않습니다.');
      }
      const mergedStart = startDate ?? (found[0]['startDate'] as string | null);
      const mergedEnd = endDate ?? (found[0]['endDate'] as string | null);
      checkPeriod(mergedStart, mergedEnd);
      // 값을 보낸 항목만 바꾼다 (보내지 않은 항목은 그대로 둔다)
      await db.execute(
        `UPDATE hr_card_item
         SET title = COALESCE(:title, title),
             detail = COALESCE(:detail, detail),
             start_date = COALESCE(CAST(:startDate AS date), start_date),
             end_date = COALESCE(CAST(:endDate AS date), end_date),
             related_person_name = COALESCE(:relatedPersonName, related_person_name),
             updated_at = now()
         WHERE hr_card_item_id = CAST(:hrCardItemId AS bigint)`,
        { hrCardItemId, title, detail, startDate, endDate, relatedPersonName },
      );
      return { hrCardItemId };
    });
  }
}

