import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  DateText,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Form,
  Field,
  TextInput,
  DateInput,
  Select,
  LookupSelect,
  RefName,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const ITEM_TYPES = ['가족', '학력', '경력', '자격·면허', '외국어', '인사고과', '상벌', '출장', '부양가족', '병역', '보훈'];
const TYPE_OPTIONS: [string, string][] = ITEM_TYPES.map((t): [string, string] => [t, t]);
const SIZE = 20;

export default function FnSfr01205Page({ role, notify }: PageProps) {
  const [draftEmployee, setDraftEmployee] = useState<number | string>('');
  const [draftType, setDraftType] = useState('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [itemType, setItemType] = useState('');
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [editing, setEditing] = useState<Row | null>(null);
  const [createForm, setCreateForm] = useState<Row>({});
  const [editForm, setEditForm] = useState<Row>({});

  const { data, error, loading, reload } = useData<Page>(async () => {
    if (employeeId === '') {
      return { items: [], page: 0, size: SIZE, total: 0 };
    }
    return call<Page>('GET', '/hr-card-items', role, undefined, { employeeId, itemType, page, size: SIZE });
  }, [employeeId, itemType, page, role]);

  const search = () => {
    setEmployeeId(draftEmployee);
    setItemType(draftType);
    setPage(0);
  };

  const reset = () => {
    setDraftEmployee('');
    setDraftType('');
    setEmployeeId('');
    setItemType('');
    setPage(0);
  };

  const openCreate = () => {
    setCreateForm({ employeeId: employeeId, itemType: itemType });
    setCreating(true);
  };

  const openEdit = (row: Row) => {
    setEditForm({
      title: row.title ?? '',
      detail: row.detail ?? '',
      startDate: row.startDate ?? '',
      endDate: row.endDate ?? '',
      relatedPersonName: row.relatedPersonName ?? '',
    });
    setDetail(null);
    setEditing(row);
  };

  const setCreateValue = (key: string, value: unknown) => {
    setCreateForm({ ...createForm, [key]: value });
  };

  const setEditValue = (key: string, value: unknown) => {
    setEditForm({ ...editForm, [key]: value });
  };

  const submitCreate = async () => {
    if (createForm.employeeId === '' || createForm.employeeId === undefined) {
      throw new Error('임직원을 선택해 주세요.');
    }
    if (!createForm.itemType) {
      throw new Error('항목 유형을 선택해 주세요.');
    }
    if (!String(createForm.title ?? '').trim()) {
      throw new Error('항목명을 입력해 주세요.');
    }
    if (createForm.startDate && createForm.endDate && String(createForm.startDate) > String(createForm.endDate)) {
      throw new Error('시작일이 종료일보다 늦을 수 없습니다.');
    }
    await call('POST', '/hr-card-items', role, createForm);
    notify('인사기록카드 항목을 등록했습니다.');
    setCreating(false);
    reload();
  };

  const submitEdit = async () => {
    if (!editing) {
      return;
    }
    if (!String(editForm.title ?? '').trim()) {
      throw new Error('항목명을 입력해 주세요.');
    }
    if (editForm.startDate && editForm.endDate && String(editForm.startDate) > String(editForm.endDate)) {
      throw new Error('시작일이 종료일보다 늦을 수 없습니다.');
    }
    await call('PATCH', '/hr-card-items/' + String(editing.hrCardItemId), role, editForm);
    notify('인사기록카드 항목을 수정했습니다.');
    setEditing(null);
    reload();
  };

  const columns: Column[] = [
    { key: 'itemType', label: '항목 유형', render: (r) => <Badge value={r.itemType} /> },
    { key: 'title', label: '항목명' },
    { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
    { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
    { key: 'relatedPersonName', label: '관련자명' },
  ];

  return (
    <div className="bento">
      <section className="box span-3">
        <h2>항목 수</h2>
        <div><Num value={data ? data.total : 0} /></div>
      </section>
      <section className="box span-12">
        <h2>인사기록카드 항목</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="임직원 ID" required>
            <LookupSelect table="employee" role={role} value={draftEmployee} onChange={setDraftEmployee} />
          </Field>
          <Field label="항목 유형">
            <Select value={draftType} onChange={setDraftType} options={TYPE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0}>
          <button type="button" onClick={openCreate}>항목 등록</button>
        </Band>
        {employeeId === '' && <p>임직원을 선택하고 조회해 주세요.</p>}
        {error && <ErrorText text={error} />}
        {loading && <p>불러오는 중입니다.</p>}
        <DataTable
          columns={columns}
          rows={data ? data.items : []}
          onRowClick={(row) => setDetail(row)}
          empty="인사기록카드 항목이 없습니다."
        />
        <Pager page={page} size={SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>

      {detail && (
        <Drawer title="인사기록카드 항목 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['임직원 ID', <RefName table="employee" role={role} value={detail.employeeId} />],
              ['항목 유형', <Badge value={detail.itemType} />],
              ['항목명', String(detail.title ?? '')],
              ['상세 내용', String(detail.detail ?? '')],
              ['시작일', <DateText value={detail.startDate} />],
              ['종료일', <DateText value={detail.endDate} />],
              ['관련자명', String(detail.relatedPersonName ?? '')],
            ]}
          />
          <button type="button" onClick={() => openEdit(detail)}>수정</button>
        </Drawer>
      )}

      {creating && (
        <Drawer title="인사기록카드 항목 등록" onClose={() => setCreating(false)}>
          <Form onSubmit={submitCreate} submit="등록">
            <Field label="임직원 ID" required>
              <LookupSelect
                table="employee"
                role={role}
                value={createForm.employeeId}
                onChange={(v) => setCreateValue('employeeId', v)}
              />
            </Field>
            <Field label="항목 유형" required>
              <Select
                value={createForm.itemType}
                onChange={(v) => setCreateValue('itemType', v)}
                options={TYPE_OPTIONS}
              />
            </Field>
            <Field label="항목명" required>
              <TextInput value={createForm.title} onChange={(v) => setCreateValue('title', v)} />
            </Field>
            <Field label="상세 내용" wide>
              <TextInput multiline value={createForm.detail} onChange={(v) => setCreateValue('detail', v)} />
            </Field>
            <Field label="시작일">
              <DateInput value={createForm.startDate} onChange={(v) => setCreateValue('startDate', v)} />
            </Field>
            <Field label="종료일">
              <DateInput value={createForm.endDate} onChange={(v) => setCreateValue('endDate', v)} />
            </Field>
            <Field label="관련자명">
              <TextInput
                value={createForm.relatedPersonName}
                onChange={(v) => setCreateValue('relatedPersonName', v)}
              />
            </Field>
          </Form>
        </Drawer>
      )}

      {editing && (
        <Drawer title="인사기록카드 항목 수정" onClose={() => setEditing(null)}>
          <Form onSubmit={submitEdit} submit="수정">
            <Field label="항목명" required>
              <TextInput value={editForm.title} onChange={(v) => setEditValue('title', v)} />
            </Field>
            <Field label="상세 내용" wide>
              <TextInput multiline value={editForm.detail} onChange={(v) => setEditValue('detail', v)} />
            </Field>
            <Field label="시작일">
              <DateInput value={editForm.startDate} onChange={(v) => setEditValue('startDate', v)} />
            </Field>
            <Field label="종료일">
              <DateInput value={editForm.endDate} onChange={(v) => setEditValue('endDate', v)} />
            </Field>
            <Field label="관련자명">
              <TextInput
                value={editForm.relatedPersonName}
                onChange={(v) => setEditValue('relatedPersonName', v)}
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
